Depth-first recursion carrying the path prefix: for a non-empty map or array recurse into each child with `prefix.key` / `prefix.index`; otherwise write the value at the prefix. O(total size) time. An explicit stack instead of recursion is equally good.

def flatten_record(record):
    out = {}

    def walk(value, path):
        if isinstance(value, dict) and value:
            for key, child in value.items():
                walk(child, path + "." + key if path else key)
        elif isinstance(value, list) and value:
            for i, child in enumerate(value):
                walk(child, path + "." + str(i))
        else:
            out[path] = value

    for key, value in record.items():
        walk(value, key)
    return out

