Buffer accepted events in a min-heap keyed by (time, arrival index). On each arrival compare with the current watermark, push, update maxSeen, then pop while the heap's minimum time ≤ watermark; flush the heap at the end. Each event is pushed and popped once: O(n log n) time, O(n) space. A sorted buffer with insertion is acceptable for partial-to-full credit depending on the stated complexity (O(n^2) worst case).

import heapq

def reorder_events(events, lateness):
    heap, emitted, dropped = [], [], []
    max_seen = None
    for seq, (time, event_id) in enumerate(events):
        watermark = None if max_seen is None else max_seen - lateness
        if watermark is not None and time < watermark:
            dropped.append(event_id)
            continue
        heapq.heappush(heap, (time, seq, event_id))
        max_seen = time if max_seen is None else max(max_seen, time)
        watermark = max_seen - lateness
        while heap and heap[0][0] <= watermark:
            emitted.append(heapq.heappop(heap)[2])
    while heap:
        emitted.append(heapq.heappop(heap)[2])
    return {"emitted": emitted, "dropped": dropped}

Map each field to its (min, max), split the field on commas, and test each item: `*`, number, range, or step (start/end from the range or the field bounds, then check value in range and (value − start) mod s = 0). All five fields must match. O(length of expr). Expanding every field into the set of allowed values and checking membership is an equally good alternative.

FIELDS = [("minute", 0, 59), ("hour", 0, 23), ("day", 1, 31), ("month", 1, 12), ("weekday", 0, 6)]

def item_matches(item, value, lo, hi):
    step = 1
    if "/" in item:
        item, s = item.split("/")
        step = int(s)
    if item == "*":
        start, end = lo, hi
    elif "-" in item:
        a, b = item.split("-")
        start, end = int(a), int(b)
    else:
        start = end = int(item)
    return start <= value <= end and (value - start) % step == 0

def cron_matches(expr, time):
    parts = expr.split(" ")
    for field, (name, lo, hi) in zip(parts, FIELDS):
        value = time[name]
        if not any(item_matches(item, value, lo, hi) for item in field.split(",")):
            return False
    return True
